            "lsn": "2D9/AD00445A"
        },
        "streams": [
            "public.table_1",
            "public.table_2"
        ]
    },
    "streams": [
        {
            "stream": "table_1",
            "namespace": "public",
            "sync_mode": "",
            "state": {
                "chunks": []
            }
